def transform(grid):
    h, w = len(grid), len(grid[0])

    # The canvas is the contiguous rectangular block of nonzero cells.
    # Find its bounding box by locating the large block of 1s.
    rlist = [r for r in range(h) if any(grid[r][c] == 1 for c in range(w))]
    clist = [c for c in range(w) if any(grid[r][c] == 1 for r in range(h))]
    r0, r1 = min(rlist), max(rlist) + 1
    c0, c1 = min(clist), max(clist) + 1
    panel = [row[c0:c1] for row in grid[r0:r1]]

    # The output is the transposed canvas. Exterior colored markers encode
    # the replacement colors for matching colored marks inside the canvas.
    out = [list(row) for row in zip(*panel)]
    external = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 1) and not (r0 <= r < r1 and c0 <= c < c1):
                external.setdefault(v, []).append((r, c))

    inner_positions = {}
    for r in range(len(panel)):
        for c in range(len(panel[0])):
            v = panel[r][c]
            if v != 1:
                inner_positions.setdefault(v, []).append((c, r))

    # Pair exterior clue colors with the panel's special colors in spatial order.
    src_colors = sorted(inner_positions)
    clue_colors = sorted(external)
    for src, dst in zip(src_colors, clue_colors):
        for rr, cc in inner_positions[src]:
            out[rr][cc] = dst
    return out
